namespace OpenTPW;

/// <summary>
/// Register of the original-save import mappings that are not traced (docs/reverse/SAVE-plan.md §8.2,
/// docs/SAVE-CONTAINER.md, "Import into OpenTPW"). Each entry has a matching <c>// [APPROX:SAVE-NNN]</c>
/// comment at its code site. Values the import drops are also reported in <see cref="OriginalEconomyImport.Evidence"/>.
/// </summary>
public static class SaveApproximations
{
	public static readonly IReadOnlyList<(string Id, string Assumption, string EvidenceNeeded)> All = new[]
	{
		("SAVE-002", "a saved guest in a queue or boarding (states 11–14), leaving a ride (15), using an attraction (16) or held by a guard (17) is not imported, nor is a park guest off the paths, a guard escorting a guest is imported idle and one chasing a guest the import does not restore gives the chase up at his first update; an imported guest in an activity (state 8) decides again at once, one at the booth (4) that was not yet weighed waits OpenTPW's booth time (ARRIVAL-006), a turn stamp before the save's turn counts from the import, and the admission flag (mBeenAdmitted, set by OnAdmittance 0x5012B0 and cleared by the dismissal 0x5012F0, which also clears the queue links), the 32-slot event ring (AddEvent 0x50C100) and the queue links (mQNext, mQPrev) are not imported", "an OpenTPW queue and rider restore for original guests"),
		("SAVE-004", "the pool's sub-type and on-pointer bytes are not imported: a candidate's sub-type (+9) is its sprite variant, drawn at its creation (0x507600 → 0x541F70: (R >> 2) % the category's loaded bank count, the table 0x763F88 of 12-byte entries (category file name, loaded count at +8, filled by the sprite loader 0x541D90 → 0x541310) that GUEST-014 also describes) and handed to the placement object 0x46C6D0 when it is picked up (0x507BF0), which also sets its on-pointer byte (+0xB; the object only stores the variant and the flag, its constructor writes them to +0x10 and +0x11); OpenTPW keeps no staff variant (GUEST-014) and does not save the placement in hand. The people-in-category counts and stop-producing flags need no import: the census 0x508000 recomputes them from the park's staff before every read (the refill 0x5084F0, its top-up 0x508170 and the pick-up 0x507BF0), as UpdatePool counts the hired staff; the opening-pool flag only gates the opening pool 0x5087D0, which OpenTPW draws for a new park only", "the staff variant of GUEST-014 (which sprite bank a hired member draws from the saved sub-type) and a placement in hand"),
		("SAVE-005", "a save whose challenge slots do not match the level's challenges (a different count or types) keeps the new park's challenge state: the original loads the 20 slots as saved (the carried object is imported); the loss counts (+0x24) and the offered words (+0x20) are read and need no import, as nothing in the challenge code reads them (0x4d1ae0, 0x4d12b7, 0x4d159b)", "challenge definitions taken from the saved slots (type, time, value, objects, prize, follow-up), where OpenTPW takes them from the level's settings"),
		("SAVE-006", "a closed open word of a working attraction (mCanLoad: the park door opens it), its sign lines (OpenTPW names no attraction), a staff claim no imported job holds (an imported job's claim is taken again with its saved turn, 0x004E01F0; any other claim is dropped, and a claim lapses 100 turns after its turn unless its claimant still targets the object, 0x004E0220, ECON-022) are not imported; the raw links (mesh instance, script and track handles, flags, footprint, entrance and exit cells, upgrade parent, balloon sprite) are rebuilt by the placement and the queue (cells, ends, called guest) from the laid queue cells", "the import of the open word, the sign lines and the staff claim into the restored rides' runtimes"),
		("SAVE-007", "lab projects OpenTPW does not list are dropped, a saved current project OpenTPW would not research now is not selected, and the save's highest open group is recomputed from the researched items and kept where it differs. The object controls' researched bytes (the control manager's table 0x4D3AA0 after the world variables, SaveObjectControls) are read and checked: only the lab's init 0x5031A0 (an object without a research cost) and the research step 0x504630 write them, and on the shipped Jungle save they agree with OpenTPW's research for every research item", "the original's research table order (ECON-017), which decides what the lab lists and which project is current when OpenTPW's info-id order differs"),
		("SAVE-009", "the staff HQ's picked-up staff id (+0x60) is not imported: it is set when a member is picked up (0x509AE0 from 0x505C50, which also sets the member's state word to 7) and read and cleared when the placement tool puts it down (0x509AF0 from 0x46CC40); OpenTPW imports the saved state 7 as picked up (StaffJob.PickedUp) but holds no placement object for the member and does not save one in hand. The force-strike word and the trained byte need no import: the force strike (+0x64) is written only by the HQ constructor 0x5089C0 (0) and the save loader 0x508BB0, so the month gate 0x508E70 and the grievance 0x509360 see 0 in play as OpenTPW does, and the trained byte (mHaveEverTrained, training +0x14) is only cleared (0x50C620) and serialized (0x50C640), never read", "what the original does with a member loaded in state 7 and the HQ's id when no placement object holds him (the loader 0x508BB0 reads +0x60 back; no placement is rebuilt that this reading found)"),
		("SAVE-010", "the advisor presentation block (its width is traced, SaveBlockWidths) and the decoded but unapplied camera, first clock word (the second is the advisor clock, applied when the automatic advisor attaches), vanilla time, game-system words, cheat bytes, advisor scoring and UI record count (SaveRuntimeBlocks: OpenTPW's start camera looks at its own focus, not the saved point of interest) and the Coasters block, whose structure SaveCoasterBlock now reads (SAVE-920 to SAVE-923) without importing any state, the weather, park analyser, tag system, mechanic HQ and UI message receiver things, the world state, arrival variables and arrival bytes, the calendar session start and the advisor controller's time signature, sound, three raw words, mRequestedLastTutorial and mMessagePlaying are not imported (its current record is imported as the last tutorial advice when an automatic advisor attaches), nor are its pending advice and history when no automatic advisor is attached; of the cell map only path cells, occupancy, MAP attributes and each path cell's texture and turn are read (so a handyman walking to or sweeping litter is imported idle), and a saved path tile is drawn only while the cell's path neighbours equal the saved ones and its turn is 0/90/180/270 (otherwise the tile is chosen from the neighbours)", "the original's post-load reconstruction of the decoded values"),
		("SAVE-011", "a Coasters block with a coaster is located by its delimiter's bytes (every other block ends where its reader stops, SaveBlockWidths, the World included since the loader 0x5179C0 is traced, then its tag must follow, like tp.exe's loader 0x415270; a Theme Park World payload's World that does not read as the original's, a synthetic payload, falls back to its delimiter too; the Theme Park Inc profile has no such fallback and reads its World exactly): a payload that splits in more than one way there, or holds the COAS delimiter's bytes more than MaximumDelimiterOccurrences times, is rejected, while the original loader runs each block's own reader and then compares the next 4 bytes with the block's tag (the tags at 0x415371 and its successors), never searching, and loads such payloads", "the coaster type's train slot and car counts (type +0x2E8 and +0x2F4) for a layout that knows the park's coaster types"),
		("SAVE-012", "Restart Park reloads OpenTPW's own snapshot (opentpw-<theme>-restart.json, the park-resume format), not the original's <save>\\restart.INTS: the original writes that file in state 15 of the park state machine 0x54E360 through 0x550B30 (skipped while the GameType word 0xFB3B7C is 1, the online visit) and reloads it for a restart request (code 1 from the confirm callbacks 0x48B5B0 and 0x48B620 through 0x5508B0: state 10 to 13, which only advances, and 14, where 0x5996D0(1) ends the running park and 0x5AC5F0 loads the file through 0x414D40, then back to 10) and takes no new snapshot after that reload; OpenTPW restarts into a park-resume snapshot instead of an original save file (which snapshot is kept is the design choice [EXT:restart-snapshot-per-start]; the camera block that is not restored belongs to SAVE-010)", "whether OpenTPW's park-resume snapshot restores everything the original's restart.INTS load does (the writer 0x5ac780 and loader 0x414D40 are the save format's twins, SAVE-010 lists what the import leaves out)"),
		("SAVE-013", "the decoded Scripts block (SaveScriptsBlock: the sprite-script slot table and each 0x118-byte VM record, tp.exe 0x475730) and Particles block (SaveParticlesBlock: the globals, 120 emitter slots, 20 effector slots and the templates, tp.exe 0x51F7A0) of an original save are read exactly but not applied to a park: SaveParticleState maps the pool onto ParticleSystemState (ParticleSystem.Restore takes it) partially (it drops the emitter hold, group, screen-space, ring and immortal words, the bounds, the effector group, mode and strength, the pool capacity, density and low-detail flag and the saved template tables, so modified templates 101 to 104 restore as the file's; the corpus loses nothing) and the import does not call it, so the park's ambient emitters (the saved WaterFall and Button emitters) restart from the level's own requests; no OpenTPW system runs the sprite-script table at 0x74DAB8 (the balloon, burst and entertainer steps use their own timing, GUEST-017), so the saved program counters, wake ticks and positions have no counterpart; the effector slot stores no template id, which SaveParticleState recovers from template bytes the tick does not write by direct displacement (writes through a base register were not checked; no corpus save has a live effector)", "whether restoring the saved ambient emitters changes what the player sees (the level requests its own at load), the sprite-script program words at 0x74DAB8 to run a saved counter, and a save with a live effector to confirm the template match"),
		("SAVE-920", "no runtime coaster is rebuilt from a decoded Coasters block (the body between the stored EMAK and SAOC delimiters): the reader decodes the headers, sections and trains of every saved coaster once the coaster type's train and car counts are known (the park import takes them from the level's coaster .sam), but ParkObjects.ImportOriginal refuses a park whose block lists a coaster, because the original's loader (tp.exe 0x437B60) rebuilds each coaster's controller, track nodes, links, trains and cars from it and OpenTPW's coaster runtime has no such restore from the original's words; a park without coaster imports as before", "a Theme Park World save with a built coaster to check the decoded block on real bytes, and the restore of a CoasterRide's track and trains from SaveCoaster, SaveCoasterSection and SaveCoasterTrain"),
		("SAVE-921", "the coaster header's flag word is kept raw: the saver (tp.exe 0x437300) writes controller +0x3C bits 0 and 1 as wire 0x1 and 0x2 (the track is complete, the circuit is cut open: SaveCoaster.TrackComplete and CircuitOpen) and the track flags (+0) 0x20 to 0x800 as wire 0x4 to 0x100 (0x43743C..0x4374D0), and the loader maps them back (0x4380D4..0x438335); the section flag word is decoded (SaveCoasterSectionFlags: wire 0x1/0x2/0x4 and the cut, link and intersection marks are restored, wire 0x8/0x10/0x20 are the loop and zero-bank flags the node constructor derives again), but the meaning of the track flags 0x20, 0x80, 0x100, 0x200 and 0x400 is not traced (0x40 is the outside mode and 0x800 is cleared when the trains are removed, COAST-plan §22)", "what sets and reads the controller's track flags 0x20, 0x80, 0x100, 0x200 and 0x400 (controller +0)"),
		("SAVE-922", "the coaster header words +12, +20, +28, +32, +244 and +240 and the block's three globals are saved but only partly understood, they are reported raw. Traced in tp.exe's loader 0x437B60: the controller word +16 is the station's mesh instance id (SaveCoaster.StationMeshInstanceId) matched against the live coasters' +0x10 to bind the block to an existing coaster (0x437CBF; none matching dereferences null, 0x437CD5), +8 is the controller state word (the low nibble is the CoasterControllerState), the three globals and the words +20 and +28 go to the coaster slot allocator 0x468760 (state 0x790B04, 0x790B00, 0x791CE0), whose slot is stored in the controller's +0x14, and +240 is restored to the controller's +0xF0 (0x438373), which 0x43BA90 copies to the room capacity +0xB8 (0x43BBD1); the section words are decoded (the mesh instance +112, bank +216, incline +220, yaw +224, height parameter +232 and loop rotation +248, setters 0x444150, 0x4441D0 and 0x444270) and the auxiliary ordinals are the link ordinals of the node with ordinal 2", "the readers of the controller words +12, +32 and +244 and what the slot allocator 0x468760 does with +20 and +28 and the three globals"),
		("SAVE-923", "the train words +0x38, +0x64 and +0x68, the car's flag word and the car byte +0x44 are kept raw, no original coaster chunk is written. The layout is decoded in tp.exe (saver 0x437300, loader 0x437B60) and read by SaveCoasterTrain: per train slot a 27-byte record (train flags +0, the car count +0xC, +0x74 the reference car's position, +0x78 the speed, +0x10 the riders; 0x43783B), then per car an 11-byte record (car +0, counts A and B from car +0x30/+0x34, +0x44, the car's mesh instance +0xC; 0x4378A5) and A then B u32 entries from the car's lists +0x28/+0x2C (the riders on the lap and the guests seated at the station); nothing in the train step 0x43CE20, the layout 0x43CBDA or the station step 0x43B8B0 reads the raw words", "the writers and readers of train +0x38, +0x64 and +0x68 and of car +0 and +0x44"),
		("SAVE-940", "the names of the Theme Park Inc attraction's 19 history rings (ThemeParkIncAttractionRing) are descriptions of what the game adds to each ring, read from the code that increments it (the history object 0x5ea020, the end-of-visit step 0x6118d0, the guest outcome step 0x612740 and the price test 0x6120c0), not names the loader's log gives: the order, capacities, periods (a new-day message 11 and a new-month message 12 from the calendar step 0x6083d0) and the money, customer, walk-away, mood-grade and price rings are traced, but DailyRatedVisits, DailyDeclinedGuests and DailyFailedIngredientChecks stand for several or only partly identified conditions (the info words they test, +0x200/+0x204/+0x21c, and the guest thresholds 0xa01b1c..0xa01b44 are unnamed), and the prebuilt's rings are all empty, so no ring value has been seen in a save", "a Theme Park Inc save whose attractions have run, and the info fields +0x200, +0x204 and +0x21c"),
		("SAVE-944", "the Theme Park Inc guest (model 1), staff (4 to 8) and gardener (20) bodies have no witnessed save: their layouts (a guest is 619 bytes; a staff member 684 to 696 bytes plus 4 for each saved entry of its six history rings, at most 30 each) are read from the load routines of Game.exe (guest 0x60d260, staff base 0x6267c0 and the role loads, ring 0x62f2b0) and checked only against an emulation of those routines, never against a save's bytes. For all traced bodies (also the staff HQ, advisor controller, park analyser, research lab, weather and challenge system, whose prebuilt widths the layouts reproduce) a word keeps its stored width because the loaders copy each member, so a field's signedness or float type, and the meaning of a ring, are not known; a ring count above its capacity (30, 3, 144, 50 or 5 entries; the byte ring is 50, its 51st slot being padding, so the original overruns only from entry 52) is refused, although the original would read on, and a count with the sign bit set is refused where the original compares signed and reads no entry. Guests, staff and gardeners have never been checked against a real save, and a layout mistake now refuses the whole save where the old header search recovered", "a Theme Park Inc save with guests, staff or a gardener to check the layouts on real bytes, and the users of the words to type them"),
	};
}
